  if not exists (select 1 from reading_passages where title = $q$How the Piano Displaced the Harpsichord$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$How the Piano Displaced the Harpsichord$q$, $q$For most of the seventeenth century, the harpsichord was the leading keyboard instrument in European music. Pressing a key caused a small quill to pluck a string, producing a bright and precise sound. Because the quill plucked with the same force however hard the player pressed, the instrument could not grow louder or softer under the fingers. Builders worked around this limit by adding extra sets of strings and keyboards that the player could switch between. The result was a range of contrasting tone colors, but not the gradual swell that singers and violinists took for granted.

Around 1700, Bartolomeo Cristofori, who cared for the instruments of the Medici court in Florence, built a keyboard that struck its strings with small hammers. His mechanism threw each hammer at the string and then let it fall back at once, so the string could go on ringing freely. Because the hammer moved faster when the key was pressed harder, the player could shape the volume of every note. Cristofori called his invention a harpsichord with soft and loud, a phrase later shortened to pianoforte and finally to piano. Few musicians paid attention at first, and the instrument remained a curiosity for several decades.

German builders improved the action during the eighteenth century, and composers slowly began writing music that depended on changes of volume. Mozart performed on pianos in Vienna, and by the end of the century publishers were advertising sonatas for the newer instrument. Nineteenth-century makers added iron frames, thicker strings and felt-covered hammers, producing a tone powerful enough for large concert halls. The harpsichord, which could not compete in such spaces, almost disappeared from musical life for a hundred years. It returned only in the twentieth century, when performers rediscovered it in order to play older music in something closer to its original sound.$q$, $q$arts / music$q$, 5, 303, true, $q$reading_shabbat_2026-09-05_E1$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Cristofori's hammer mechanism was the most complicated device built during his century.", "Harpsichord builders added extra keyboards in order to imitate the sound of the human voice.", "The piano replaced the harpsichord because it let players control the volume of each note.", "Concert halls of the nineteenth century were too large for most instruments of the period."]$q$::jsonb, 2, $q$["לא נכון. הקטע מתאר את המנגנון של קריסטופורי אך אינו טוען שהיה המכשיר המורכב ביותר במאה שלו.", "לא נכון. הפסקה הראשונה מסבירה שהמקלדות הנוספות נועדו לגוונים מנוגדים, לא לחיקוי הקול האנושי.", "נכון. הקטע בנוי סביב מגבלת עוצמת הקול של הצ'מבלו ופתרונה בפסנתר, ומסביר כך את ההחלפה בין שני הכלים.", "לא נכון. גודל אולמות הקונצרטים הוא פרט בפסקה השלישית התומך בטיעון, ולא הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch E1, passage=piano-harpsichord, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, harpsichord builders added extra sets of strings and keyboards in order to —$q$, $q$["make the instrument easier for beginners to learn", "reduce the cost of building a large and complicated keyboard instrument", "allow the player to press the keys with far greater physical force", "offer contrasting tone colors despite the fixed volume of each note"]$q$::jsonb, 3, $q$["לא נכון. הפסקה אינה עוסקת כלל בקלות הלימוד של הכלי.", "לא נכון. הפסקה אינה מזכירה שיקולי עלות בבניית הכלי.", "לא נכון. הפסקה מציינת שעוצמת הפריטה לא הושפעה מכוח הלחיצה כלל.", "נכון. הפסקה הראשונה מסבירה שהתוספות נועדו לעקוף את מגבלת עוצמת הקול, והתוצאה הייתה מגוון של גוונים מנוגדים."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["adding extra sets of strings and keyboards that the player could switch between"]$q$::jsonb, $q$shabbat batch E1, passage=piano-harpsichord, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["describe how Cristofori's hammer action gave the player control over volume.", "explain why the harpsichord nearly vanished from European musical life.", "list the composers who wrote sonatas for the newly invented instrument.", "describe the improvements that nineteenth-century makers introduced to the piano."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה מתארת את מנגנון הפטישים של קריסטופורי ומסבירה כיצד הוא איפשר לנגן לעצב את עוצמת כל צליל.", "לא נכון. היעלמות הצ'מבלו מתוארת בפסקה השלישית, ולא בשנייה.", "לא נכון. הסונטות והמו\"לים מופיעים בפסקה השלישית, ולא בשנייה.", "לא נכון. השיפורים של המאה התשע-עשרה מתוארים בפסקה השלישית, ולא בשנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch E1, passage=piano-harpsichord, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the last paragraph that —$q$, $q$["the harpsichord came back because audiences had grown tired of the piano's loud tone", "changes in the size of concert spaces affected which instrument survived", "Mozart preferred the harpsichord to the pianos that were available in Vienna", "iron frames were first introduced by German builders in the eighteenth century"]$q$::jsonb, 1, $q$["לא נכון. הפסקה מציינת שהצ'מבלו חזר כדי לנגן מוזיקה עתיקה בצליל קרוב למקור, ולא בגלל עייפות מהפסנתר.", "נכון. הפסקה קושרת בין הצליל החזק המתאים לאולמות גדולים לבין העובדה שהצ'מבלו לא יכול היה להתחרות במרחבים כאלה ונעלם.", "לא נכון. הפסקה מציינת שמוצרט ניגן על פסנתרים בווינה, ואינה מייחסת לו העדפה לצ'מבלו.", "לא נכון. הפסקה מייחסת את המסגרות מברזל ליצרני המאה התשע-עשרה, ולא לבנאים הגרמנים של המאה הקודמת."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch E1, passage=piano-harpsichord, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "curiosity" most nearly means —$q$, $q$["an object of interest that is not yet widely used", "a strong wish to learn about new inventions", "an instrument reserved for royal and noble households", "a device that proved impossible to build a second time"]$q$::jsonb, 0, $q$["נכון. המשפט מציין שמעטים שמו לב לכלי, ולכן 'curiosity' פירושו דבר מעניין שעדיין אינו בשימוש נרחב.", "לא נכון. כאן המילה מתארת חפץ ולא רגש של סקרנות.", "לא נכון. הפסקה אינה מגבילה את הכלי לחצרות מלוכה; היא מציינת שמעטים התעניינו בו.", "לא נכון. הפסקה אינה טוענת שהכלי לא ניתן היה לשחזור."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["the instrument remained a curiosity for several decades"]$q$::jsonb, $q$shabbat batch E1, passage=piano-harpsichord, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Prints from the Floating World$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Prints from the Floating World$q$, $q$During Japan's Edo period, city dwellers bought colored woodblock prints in enormous quantities. Known as ukiyo-e, or pictures of the floating world, they showed actors, travelers, courtesans and famous landscapes. A single print required a designer, a block cutter and a printer, and the finished sheet was cheap enough for ordinary workers to buy. Artists such as Hokusai, Hiroshige and Utamaro were commercial illustrators rather than court painters, and their work reached ordinary households.

Japan traded with the outside world only under tight restrictions until the middle of the nineteenth century. Once those limits eased, prints began arriving in European ports along with porcelain, lacquer and silk. Collectors in Paris and London bought them eagerly, and the Japanese displays at international exhibitions attracted very large crowds. By the 1870s critics had coined the term japonisme for the enthusiasm that followed.

European painters were struck less by the subjects of the prints than by the way the images were organized. Ukiyo-e artists used flat areas of color, firm outlines and high viewpoints instead of the shading and single perspective taught in the academies. They cut figures off at the edge of the sheet, allowing a bridge or a kimono to continue beyond the picture. Empty space was treated as an active part of the design rather than as an area waiting to be filled.

Vincent van Gogh collected hundreds of prints and painted careful copies of two designs by Hiroshige. Claude Monet hung his own collection at Giverny, and the cropped, off-center compositions of Edgar Degas owe an obvious debt to Japanese models. Mary Cassatt produced a series of color prints after seeing a large exhibition of Japanese work in Paris. Yet these artists were not imitating Japan so much as using its example to loosen their own inherited rules.$q$, $q$arts / visual$q$, 5, 299, true, $q$reading_shabbat_2026-09-05_E1$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["The Craft Workshops That Produced Colored Prints in the Cities of Edo Japan", "How Japanese Prints Reached Europe and Changed the Way Painters Composed", "Vincent van Gogh's Careful Copies of Two Landscape Designs by Hiroshige", "The International Exhibitions That Introduced Asian Goods to European Buyers"]$q$::jsonb, 1, $q$["לא נכון. תהליך ההפקה מתואר בפסקה הראשונה בלבד, והקטע ממשיך הרבה מעבר לכך.", "נכון. הקטע עוקב אחר הדרך שבה ההדפסים הגיעו לאירופה ומסביר כיצד שינו את אופן בניית התמונה אצל ציירים אירופיים.", "לא נכון. ההעתקים של ואן גוך הם דוגמה אחת בפסקה האחרונה, ולא נושא הקטע.", "לא נכון. התערוכות הבינלאומיות מוזכרות במשפט אחד בפסקה השנייה בלבד."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch E1, passage=ukiyo-e-europe, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
