    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["explain which features of the prints most interested European painters.", "describe the trade routes that carried Japanese goods to European ports.", "argue that academic training in perspective was of no real value to painters.", "name the European artists who assembled the largest collections of prints."]$q$::jsonb, 0, $q$["נכון. הפסקה השלישית מפרטת את המאפיינים החזותיים — שטחי צבע שטוחים, קווי מתאר, נקודות מבט גבוהות וחיתוך דמויות — שמשכו את הציירים האירופיים.", "לא נכון. דרכי המסחר מוזכרות בפסקה השנייה, ולא בשלישית.", "לא נכון. הפסקה משווה בין שתי גישות אך אינה טוענת שההכשרה האקדמית חסרת ערך.", "לא נכון. שמות האספנים מופיעים בפסקה האחרונה, ולא בשלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch E1, passage=ukiyo-e-europe, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the last sentence of the passage that European painters —$q$, $q$["eventually abandoned Japanese models and returned to their academic training", "regarded Japanese prints as technically superior to all European painting", "used Japanese prints to question the conventions they had been taught", "traveled to Japan in order to study printmaking with local masters"]$q$::jsonb, 2, $q$["לא נכון. המשפט אינו מדבר על נטישה של המודלים היפניים ועל חזרה לאקדמיה.", "לא נכון. המשפט אינו מדרג את איכות ההדפסים היפניים מול הציור האירופי.", "נכון. המשפט אומר שהאמנים השתמשו בדוגמה היפנית כדי לרופף את הכללים שירשו, כלומר כדי לערער על המוסכמות שלמדו.", "לא נכון. הקטע מתאר הדפסים שהגיעו לאירופה, ואינו מזכיר נסיעות של ציירים ליפן."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["Yet these artists were not imitating Japan so much as using its example to loosen their own inherited rules."]$q$::jsonb, $q$shabbat batch E1, passage=ukiyo-e-europe, q4$q$, 4, true);
